/** 
 * Processes the content-modify  {@link JingleIQ}.
 * @param content The {@link JingleIQ} that contains content that remotepeer wants to be modified
 */
public void processContentModify(JingleIQ content){
    if(content == null || content.getContentList() == null || content.getContentList().isEmpty()) {
        logger.info("Invalid content or empty content list");
        return;
    }

    try {
        ContentPacketExtension ext = content.getContentList().get(0);
        if(ext == null) {
            logger.info("Content extension is null");
            return;
        }

        SendersEnum senders = ext.getSenders();
        if(senders == null) {
            logger.info("Senders is null");
            return;
        }

        getMediaHandler().reinitContent(ext.getName(), senders);
    } catch (IndexOutOfBoundsException e) {
        logger.info("Failed to process content-modify: invalid content index", e);
    } catch (NullPointerException e) {
        logger.info("Failed to process content-modify: null pointer exception", e);
    } catch (Exception exc) {
        logger.info("Failed to process an incoming content-modify", exc);
        JingleIQ errResp = JinglePacketFactory.createSessionTerminate(sessionInitIQ.getTo(), sessionInitIQ.getFrom(), 
                            sessionInitIQ.getSID(), Reason.INCOMPATIBLE_PARAMETERS, "Error: " + exc.getMessage());
        setState(CallPeerState.FAILED, "Error: " + exc.getMessage());
        getProtocolProvider().getConnection().sendPacket(errResp);
    }
}
